from collections import deque
from timeit import timeit


class Pile:
    def __init__(self):
        self._elements = []

    def est_vide(self):
        return len(self._elements) == 0

    def empiler(self, element):
        self._elements.append(element)

    def depiler(self):
        if self.est_vide():
            raise IndexError('depiler() sur une pile vide')
        return self._elements.pop()

    def sommet(self):
        if self.est_vide():
            raise IndexError('sommet() sur une pile vide')
        return self._elements[-1]

    def taille(self):
        return len(self._elements)


class File:
    def __init__(self):
        self._elements = deque()

    def est_vide(self):
        return len(self._elements) == 0

    def enfiler(self, element):
        self._elements.append(element)

    def defiler(self):
        if self.est_vide():
            raise IndexError('defiler() sur une file vide')
        return self._elements.popleft()

    def premier(self):
        if self.est_vide():
            raise IndexError('premier() sur une file vide')
        return self._elements[0]

    def taille(self):
        return len(self._elements)


class FileBornee:
    def __init__(self, capacite):
        self._capacite = capacite
        self._table = [None] * capacite
        self._tete = 0
        self._queue = 0
        self._compteur = 0

    def est_vide(self):
        return self._compteur == 0

    def est_pleine(self):
        return self._compteur == self._capacite

    def enfiler(self, element):
        if self.est_pleine():
            raise IndexError('enfiler() sur une file pleine')
        self._table[self._queue] = element
        self._queue = (self._queue + 1) % self._capacite
        self._compteur += 1

    def defiler(self):
        if self.est_vide():
            raise IndexError('defiler() sur une file vide')
        element = self._table[self._tete]
        self._table[self._tete] = None
        self._tete = (self._tete + 1) % self._capacite
        self._compteur -= 1
        return element


def index_mots(texte):
    index = {}
    mot = ''
    for caractere in texte.lower() + ' ':
        if caractere.isalpha():
            mot += caractere
        elif mot:
            index[mot] = index.get(mot, 0) + 1
            mot = ''
    return index


def comparer_couts(n):
    def avec_liste():
        contenu = []
        for i in range(n):
            contenu.insert(0, i)
        return contenu

    def avec_deque():
        contenu = deque()
        for i in range(n):
            contenu.appendleft(i)
        return contenu

    return timeit(avec_liste, number=1), timeit(avec_deque, number=1)


if __name__ == '__main__':
    pile = Pile()
    for valeur in (4, 1, 7):
        pile.empiler(valeur)
    print('pile ->', pile.depiler())

    file = File()
    for valeur in (4, 1, 7):
        file.enfiler(valeur)
    print('file ->', file.defiler())

    bornee = FileBornee(3)
    bornee.enfiler('a')
    bornee.enfiler('b')
    print('file bornee ->', bornee.defiler())

    print(index_mots('le chat dort, le chien dort'))

    n = 50000
    temps_liste, temps_deque = comparer_couts(n)
    print('list.insert(0) :', round(temps_liste, 3), 's')
    print('deque.appendleft :', round(temps_deque, 3), 's')

    try:
        pile.depiler()
        pile.depiler()
        pile.depiler()
        pile.depiler()
    except IndexError as erreur:
        print('cas limite traite :', erreur)
